#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const GENERATED_MARKERS = [
  "Code generated",
  "DO NOT EDIT",
  "AUTOGENERATED",
  "This file is generated",
];

function main() {
  const args = parseArgs(process.argv.slice(2));
  const ts = loadTypeScript(args.root);
  const files = trackedTypeScriptFiles(args.root, args.includeGenerated);
  const candidates = [];

  for (const relativePath of files) {
    const absolutePath = path.join(args.root, relativePath);
    const sourceText = fs.readFileSync(absolutePath, "utf8");
    const sourceFile = ts.createSourceFile(
      absolutePath,
      sourceText,
      ts.ScriptTarget.Latest,
      true,
      absolutePath.endsWith(".tsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
    );

    for (const statement of sourceFile.statements) {
      if (!ts.isVariableStatement(statement)) {
        continue;
      }
      if (
        (statement.declarationList.flags & ts.NodeFlags.Const) !== ts.NodeFlags.Const
      ) {
        continue;
      }
      for (const declaration of statement.declarationList.declarations) {
        if (!ts.isIdentifier(declaration.name) || !declaration.initializer) {
          continue;
        }
        const rhs = typeScriptSimpleAliasExpr(ts, declaration.initializer);
        if (rhs === null) {
          continue;
        }
        const { line, character } = sourceFile.getLineAndCharacterOfPosition(
          declaration.name.getStart(sourceFile, false),
        );
        candidates.push({
          language: "typescript",
          path: toPosixPath(relativePath),
          line: line + 1,
          column: character + 1,
          scope: "module",
          name: declaration.name.text,
          rhs,
          kind: "typescript-const",
        });
      }
    }
  }

  process.stdout.write(`${JSON.stringify(candidates, null, 2)}\n`);
}

function parseArgs(argv) {
  let root = path.resolve(
    path.dirname(fileURLToPath(import.meta.url)),
    "..",
    "..",
  );
  let includeGenerated = false;
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === "--root") {
      root = path.resolve(argv[index + 1]);
      index += 1;
      continue;
    }
    if (argument === "--include-generated") {
      includeGenerated = true;
      continue;
    }
    throw new Error(`Unknown argument: ${argument}`);
  }
  return { root, includeGenerated };
}

function loadTypeScript(root) {
  const require = createRequire(import.meta.url);
  const typeScriptPath = path.join(root, "frontend", "node_modules", "typescript");
  try {
    return require(typeScriptPath);
  } catch (error) {
    throw new Error(
      `Could not load TypeScript from ${typeScriptPath}. Run dev_install.sh or pnpm install in frontend.`,
    );
  }
}

function trackedTypeScriptFiles(root, includeGenerated) {
  const output = execFileSync("git", ["-C", root, "ls-files", "-z"], {
    encoding: "utf8",
  });
  return output
    .split("\0")
    .filter(Boolean)
    .filter((relativePath) => {
      if (!relativePath.endsWith(".ts") && !relativePath.endsWith(".tsx")) {
        return false;
      }
      if (relativePath.endsWith(".d.ts")) {
        return false;
      }
      if (includeGenerated) {
        return true;
      }
      return !isGeneratedFile(root, relativePath);
    })
    .sort();
}

function isGeneratedFile(root, relativePath) {
  const normalized = toPosixPath(relativePath);
  if (`/${normalized}/`.includes("/generated/")) {
    return true;
  }
  if (normalized.startsWith("frontend/generation/")) {
    return true;
  }
  const header = fs.readFileSync(path.join(root, relativePath), "utf8").slice(0, 512);
  return GENERATED_MARKERS.some((marker) => header.includes(marker));
}

function typeScriptSimpleAliasExpr(ts, node) {
  let current = node;
  while (
    ts.isParenthesizedExpression(current) ||
    ts.isAsExpression(current) ||
    ts.isTypeAssertionExpression(current) ||
    ts.isSatisfiesExpression(current) ||
    ts.isNonNullExpression(current)
  ) {
    current = current.expression;
  }

  if (ts.isIdentifier(current)) {
    return current.text;
  }
  if (ts.isPropertyAccessExpression(current)) {
    const base = typeScriptSimpleAliasExpr(ts, current.expression);
    if (base === null) {
      return null;
    }
    return `${base}.${current.name.text}`;
  }
  return null;
}

function toPosixPath(value) {
  return value.split(path.sep).join("/");
}

main();
